{"content":""""Chess best-move solver using Minimax with Alpha-Beta pruning."""
import chess

MATE_SCORE = 100000
PIECE_VALUES = {
    chess.PAWN: 100,
    chess.KNIGHT: 320,
    chess.BISHOP: 330,
    chess.ROOK: 500,
    chess.QUEEN: 900,
    chess.KING: 0,
}


def evaluate(board: chess.Board) -> int:
    """Static evaluation from the perspective of the side to move (centipawns)."""
    if board.is_checkmate():
        # Side to move is mated -> very bad
        return -MATE_SCORE
    if board.is_stalemate() or board.is_insufficient_material():
        return 0
    # Material balance from White's perspective
    score = 0
    for piece_type, value in PIECE_VALUES.items():
        score += len(board.pieces(piece_type, chess.WHITE)) * value
        score -= len(board.pieces(piece_type, chess.BLACK)) * value
    # Return from side-to-move perspective (negamax convention)
    if board.turn == chess.BLACK:
        score = -score
    # Small mobility bonus
    score += board.legal_moves.count() * 2
    return score


def order_moves(board: chess.Board):
    """Order moves: mates/checks/captures/promotions first for better pruning."""
    moves = list(board.legal_moves)

    def move_score(move):
        s = 0
        # Captures scored by MVV-LVA
        if board.is_capture(move):
            captured = board.piece_at(move.to_square)
            attacker = board.piece_at(move.from_square)
            cap_val = PIECE_VALUES.get(captured.piece_type, 0) if captured else 100
            att_val = PIECE_VALUES.get(attacker.piece_type, 0) if attacker else 0
            s += 10000 + cap_val - att_val
        if move.promotion:
            s += 9000 + PIECE_VALUES.get(move.promotion, 0)
        # Checks get a bonus (prioritize checks after captures)
        board.push(move)
        is_mate = board.is_checkmate()
        is_check = board.is_check()
        board.pop()
        if is_mate:
            s += 20000
        elif is_check:
            s += 5000
        return s

    moves.sort(key=move_score, reverse=True)
    return moves


def quiescence(board: chess.Board, alpha: int, beta: int, ply: int) -> int:
    if board.is_checkmate():
        return -MATE_SCORE + ply
    if board.is_stalemate() or board.is_insufficient_material():
        return 0
    stand_pat = evaluate(board)
    if stand_pat >= beta:
        return beta
    if alpha < stand_pat:
        alpha = stand_pat
    for move in order_moves(board):
        if not board.is_capture(move) and not move.promotion:
            continue
        # Avoid non-checking quiet extension issues: still need legality
        board.push(move)
        score = -quiescence(board, -beta, -alpha, ply + 1)
        board.pop()
        if score >= beta:
            return beta
        if score > alpha:
            alpha = score
    return alpha


def negamax(board: chess.Board, depth: int, alpha: int, beta: int, ply: int) -> int:
    if board.is_checkmate():
        return -MATE_SCORE + ply
    if board.is_stalemate() or board.is_insufficient_material():
        return 0
    if board.is_seventyfive_moves() or board.is_fivefold_repetition():
        return 0
    if depth <= 0:
        return quiescence(board, alpha, beta, ply)
    best = -MATE_SCORE - 1
    for move in order_moves(board):
        board.push(move)
        score = -negamax(board, depth - 1, -beta, -alpha, ply + 1)
        board.pop()
        if score > best:
            best = score
        if score > alpha:
            alpha = score
        if alpha >= beta:
            break
    return best


def find_best_move(board: chess.Board, max_depth: int = 4):
    legal = order_moves(board)
    if not legal:
        return None
    # 1. Immediate forced mate-in-1: fastest and unambiguous
    for move in legal:
        board.push(move)
        if board.is_checkmate():
            board.pop()
            return move
        board.pop()
    # 2. Full alpha-beta search with iterative deepening
    best_move = legal[0]
    for depth in range(1, max_depth + 1):
        alpha = -MATE_SCORE - 1
        beta = MATE_SCORE + 1
        local_best = best_move
        local_best_score = -MATE_SCORE - 1
        for move in order_moves(board):
            board.push(move)
            score = -negamax(board, depth - 1, -beta, -alpha, 1)
            board.pop()
            if score > local_best_score:
                local_best_score = score
                local_best = move
            if score > alpha:
                alpha = score
        best_move = local_best
        # Early exit if forced mate found (already fastest due to ply penalty)
        if local_best_score >= MATE_SCORE - 50:
            break
    return best_move


def main():
    with open("/app/position.fen", "r") as f:
        fen = f.read().strip()
    board = chess.Board(fen)
    if board.legal_moves.count() == 0:
        raise ValueError("No legal moves in position")
    # Adapt depth: deeper when few pieces / few moves
    n_moves = board.legal_moves.count()
    if n_moves <= 10:
        depth = 5
    elif n_moves <= 25:
        depth = 4
    else:
        depth = 3
    best = find_best_move(board, max_depth=depth)
    san = board.san(best)
    # Write EXACTLY the SAN with no whitespace/newline
    with open("/app/best_move.txt", "w") as f:
        f.write(san)


if __name__ == "__main__":
    main()
